// Улучшенный файл utils/chartConfig.js с исправлениями для всех графиков

export const getChartConfig = (darkMode) => {
  const colors = darkMode ? {
    text: '#D1D4DC',
    grid: '#2A2E39'
  } : {
    text: '#374151',
    grid: '#e5e7eb'
  };

  return {
    // Увеличенные отступы для предотвращения обрезания данных
    margin: { top: 20, right: 30, left: 60, bottom: 30 },

    // Конфигурация оси X
    xAxisConfig: {
      tick: { fill: colors.text },
      stroke: colors.grid,
      height: 45,
      dy: 10,
      label: {
        value: 'Year',
        position: 'insideBottom',
        offset: 15,
        fill: colors.text
      }
    },

    // Конфигурация оси Y с увеличенным пространством для подписей
    yAxisConfig: {
      tick: { fill: colors.text },
      stroke: colors.grid,
      width: 80, // Увеличено с 60 для большего пространства
      tickFormatter: (value) => value.toLocaleString(), // Форматирование с разделителями
    },

    // Улучшенное форматирование больших чисел
    formatLargeNumber: (value) => {
      if (value >= 1000000) {
        return `${(value / 1000000).toFixed(1)}M`;
      } else if (value >= 1000) {
        return `${(value / 1000).toFixed(0)}K`;
      }
      return value.toLocaleString(); // Добавление разделителей тысяч
    },

    // Усовершенствованная конфигурация для отображения символа валюты
    getCurrencyLabel: (currencySymbol) => ({
      value: currencySymbol,
      angle: -90, // Вертикальный поворот для лучшего размещения
      position: 'insideLeft',
      offset: 45, // Увеличенный отступ
      dx: -10, // Горизонтальное смещение
      fill: colors.text,
      style: {
        fontSize: '14px',
        fontWeight: 'bold'
      }
    }),

    // Форматирование валютных значений для графиков
    formatCurrencyValue: (value, currencySymbol) => {
      return `${currencySymbol}${value.toLocaleString()}`;
    }
  };
};
